import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { AlertTriangle, Clock, AlertCircle, Shield, Gift, CheckCircle, RefreshCw, Lock } from 'lucide-react';
import { useFirebaseAuth } from '@/contexts/FirebaseAuthContext';
import { signOut as firebaseSignOut } from 'firebase/auth';
import { auth, db } from '@/firebase';
import { doc, onSnapshot } from 'firebase/firestore';
import { toast } from 'sonner';
import { FreeTrialService } from '@/utils/freeTrialService';
import { isSubscriptionValid, activateUserSubscription, SubscriptionPlan } from '@/utils/subscriptionService'
import { createSubscriptionWhatsAppLink } from '@/utils/whatsappService';

export default function PendingApprovalPage() {
  const { user, signOut, userSubscription, isSubscriptionActive, checkSubscriptionStatus } = useFirebaseAuth();
  const navigate = useNavigate();
  const [isActivatingTrial, setIsActivatingTrial] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [hasUsedTrial, setHasUsedTrial] = useState(false);
  const [isOnFreeTrial, setIsOnFreeTrial] = useState(false);
  const [trialDurationHours, setTrialDurationHours] = useState<number>(24);
  
  // تكوين الباقات بنفس تصميم النافذة المنبثقة
  const PLANS = [
    {
      title: 'الباقة الشهرية',
      price: 200,
      features: ['دعم مجاني كامل', 'تحديثات مستمرة', 'التحويل المباشر من التطبيق', '20 محفظة'],
      bg: 'from-blue-50 to-indigo-50',
    },
    {
      title: 'الباقة الربع سنوية',
      price: 450,
      features: ['دعم مميز', 'حتى 30 محفظة', 'التحويل المباشر من التطبيق', 'استقبال رسائل السحب والتحويل على تلجرام'],
      bg: 'from-emerald-50 to-green-50',
    },
    {
      title: 'الباقة النصف سنوية',
      price: 750,
      features: ['دعم ممتاز', 'عدد محافظ مفتوح', 'التحويل المباشر من التطبيق', 'استقبال السحب والتحويل الاوتومتيك'],
      bg: 'from-orange-50 to-amber-50',
    },
    {
      title: 'الباقة السنوية',
      price: 1450,
      features: ['دعم ممتاز', 'عدد محافظ مفتوح', 'التحويل المباشر من التطبيق', 'استقبال رسائل السحب والتحويل على تلجرام'],
      bg: 'from-purple-50 to-pink-50',
    },
    {
      title: 'باقة مدى الحياة',
      price: 4000,
      features: ['دعم ممتاز', 'عدد محافظ مفتوح', 'التحويل المباشر من التطبيق', 'استقبال رسائل السحب والتحويل على تلجرام'],
      bg: 'from-orange-50 to-amber-50',
    },
  ];

  // استماع فوري لتغيرات حالة المستخدم في Firestore
  useEffect(() => {
    if (!user?.uid) return;

    // استماع مباشر للتغيرات على وثيقة المستخدم
    const unsubscribe = onSnapshot(
      doc(db, 'users', user.uid),
      (snapshot) => {
        if (snapshot.exists()) {
          const data = snapshot.data();
          const accountActive = data.isActive !== false;

          // التحقق من الاشتراك
          const sub = data.subscription;
          const subActive = sub?.isActive === true && isSubscriptionValid(sub);

          // التحقق من باقة الفروع
          const branchActive = data.branchPackage?.status === 'active';

          // التحقق من كون المستخدم فرعاً (Branch User)
          const isBranchUser = data.isBranch === true && data.isActive === true;

          // التحقق من التجربة المجانية
          const trialActive = data.isOnFreeTrial === true;

          // إذا أصبح المستخدم نشطاً بأي طريقة، نوجهه فوراً
          if (accountActive && (subActive || branchActive || trialActive || isBranchUser)) {
            console.log('✅ PendingApprovalPage (Realtime): User activated, redirecting...');
            sessionStorage.removeItem('dashboard_kick_signature');
            try {
              localStorage.removeItem(`sub_cache_${user?.uid}`);
            } catch {}
            try {
              window.dispatchEvent(new Event('app:softRefresh'));
            } catch {}
            navigate('/user/dashboard', { replace: true });
          }
        }
      },
      (err) => {
        console.warn('مستمع users (صفحة التفعيل):', err);
      }
    );

    return () => unsubscribe();
  }, [user?.uid, navigate]);

  // مراقبة حالة المستخدم والاشتراك باستخدام Context (احتياطي)
  useEffect(() => {
    if (!user?.uid) return;
    // ننتظر حتى تتوفر بيانات الاشتراك
    if (!userSubscription) return;

    console.log('🔍 PendingApprovalPage: Checking subscription via Context:', user.uid);

    const userData = userSubscription as any;

    // التحقق من حالة الحساب العامة أولاً
    if (userData.isActive === false) {
      console.log('⛔ PendingApprovalPage: User account is deactivated (isActive=false), staying on page.');
      sessionStorage.removeItem('dashboard_kick_signature');
      return;
    }

    // دالة مساعدة لتوليد توقيع الحالة
    const generateStateSignature = (u: any) => {
      if (!u) return 'null';
      const sub = u.subscription;
      const activatedAt = sub?.activatedAt ? (sub.activatedAt.toDate ? sub.activatedAt.toDate().toISOString() : new Date(sub.activatedAt).toISOString()) : 'null';
      const plan = sub?.planType || 'null';
      const isActive = u.isActive !== false;
      const subActive = sub?.isActive === true;
      const branchActive = u.branchPackage?.status === 'active';
      const branchActivatedAt = u.branchPackage?.activatedAt ? (u.branchPackage.activatedAt.toDate ? u.branchPackage.activatedAt.toDate().toISOString() : new Date(u.branchPackage.activatedAt).toISOString()) : 'null';
      return `${isActive}|${subActive}|${plan}|${activatedAt}|${branchActive}|${branchActivatedAt}`;
    };

    const currentSignature = generateStateSignature(userData);
    const kickedSignature = sessionStorage.getItem('dashboard_kick_signature');

    const accountActive = userData.isActive !== false;
    const branchActive = userData.branchPackage?.status === 'active';
    const sub = userData.subscription;
    const valid = sub && sub.isActive === true && isSubscriptionValid(sub);
    const trialActive = userData.isOnFreeTrial === true;

    // إذا كانت الحالة نشطة، نقوم بالتوجيه
    if (accountActive && (branchActive || valid || isSubscriptionActive || trialActive)) {
      if (kickedSignature && currentSignature === kickedSignature) {
        // Still in kicked state with same signature
      } else {
        sessionStorage.removeItem('dashboard_kick_signature');
        navigate('/user/dashboard', { replace: true });
      }
    }
  }, [user?.uid, userSubscription, isSubscriptionActive, navigate]);

  // تحميل حالة التجربة المجانية للمستخدم لإخفاء خيار التجربة بعد استخدامها
  useEffect(() => {
    const loadTrialState = async () => {
      if (!user?.uid) return;
      try {
        const data = await FreeTrialService.getTrialData(user.uid);
        setHasUsedTrial(data.hasUsedFreeTrial);
        setIsOnFreeTrial(data.isOnFreeTrial);
      } catch (e) {
        console.error('خطأ في تحميل حالة التجربة المجانية:', e);
      }
    };
    loadTrialState();
  }, [user?.uid]);

  useEffect(() => {
    (async () => {
      try {
        const hours = await FreeTrialService.getTrialDurationHours();
        setTrialDurationHours(hours);
      } catch (e) {
        console.error('خطأ في تحميل مدة التجربة المجانية:', e);
      }
    })();
  }, []);

  const handleSignOut = async () => {
    try {
      await firebaseSignOut(auth);
      // مسح بعض البيانات المحلية الأساسية يدوياً لضمان تجربة نظيفة
      try {
        localStorage.removeItem(`sub_cache_${user?.uid}`);
        localStorage.removeItem(`profile_cache_v2_${user?.uid}`);
      } catch {}
      // استخدام window.location لفرض التوجيه وتجاوز أي حالات تداخل
      window.location.href = '/user/login';
    } catch (error) {
      console.error('Logout error:', error);
      // حتى لو فشل تسجيل الخروج، نوجه المستخدم
      window.location.href = '/user/login';
    }
  };

  const handleActivateZeroPlan = async () => {
    if (!user?.uid) return;

    setIsActivatingTrial(true);
    try {
      await activateUserSubscription(user.uid, SubscriptionPlan.ZERO, user.uid);
      toast.success('تم تفعيل باقة الزيرو! جاري التوجيه...');
      setTimeout(() => {
        try { navigate('/user/dashboard', { replace: true }); } catch {}
      }, 1200);
    } catch (error) {
      console.error('Error activating zero plan:', error);
      toast.error('حدث خطأ في تفعيل باقة الزيرو');
    } finally {
      setIsActivatingTrial(false);
    }
  };

  const handleActivateTrial = async () => {
    if (!user?.uid) return;
    
    setIsActivatingTrial(true);
    try {
      const result = await FreeTrialService.startFreeTrial(user.uid);
      if (result.success) {
        toast.success(result.message || `تم تفعيل التجربة المجانية لمدة ${trialDurationHours} ${trialDurationHours >= 3 && trialDurationHours <= 10 ? 'ساعات' : trialDurationHours === 2 ? 'ساعتين' : 'ساعة'}! جاري التوجيه...`);
        // توجيه فوري بدون تأخير
        try { localStorage.removeItem(`sub_cache_${user?.uid}`); } catch {}
        try { window.dispatchEvent(new Event('app:softRefresh')); } catch {}
        navigate('/user/dashboard', { replace: true });
      } else {
        toast.error(result.message);
      }
    } catch (error) {
      console.error('Error activating trial:', error);
      toast.error('حدث خطأ في تفعيل التجربة المجانية');
    } finally {
      setIsActivatingTrial(false);
    }
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    console.log('🔄 PendingApprovalPage: Manual refresh triggered');
    
    try {
      // مسح علامة الطرد لإجبار إعادة التحقق
      sessionStorage.removeItem('dashboard_kick_signature');
      
      // إعادة فحص حالة الاشتراك
      await checkSubscriptionStatus();
      
      // التحقق مما إذا كان يجب التوجيه الآن
      if (user?.uid) {
        // نستخدم import ديناميكي لتجنب مشاكل التبعيات الدائرية إن وجدت، ولضمان نسخة جديدة
        const { getDoc, doc } = await import('firebase/firestore');
        const { db } = await import('@/firebase');
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        
        if (userDoc.exists()) {
          const userData = userDoc.data();
          const accountActive = userData.isActive !== false;
          const subActive = userData.subscription?.isActive === true;
          const branchActive = userData.branchPackage?.status === 'active';
          
          if (accountActive && (subActive || branchActive)) {
             toast.success('تم تحديث البيانات، جاري التوجيه...');
             setTimeout(() => {
                navigate('/user/dashboard', { replace: true });
             }, 500);
             return;
          }
        }
      }
      
      toast.success('تم تحديث البيانات');
    } catch (error) {
      console.error('❌ Error during manual refresh:', error);
      toast.error('حدث خطأ أثناء التحديث');
    } finally {
      setIsRefreshing(false);
    }
  };

  const openWhatsApp = (plan: string, price: number, features: string[]) => {
    try {
      const text = encodeURIComponent(
        `أرغب في الاشتراك في ${plan} بسعر ${price} ج\nالمميزات:\n- ${features.join('\n- ')}`
      );
      window.open(`https://wa.me/201000392539?text=${text}`, '_blank');
    } catch {}
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <div className="w-full max-w-5xl bg-white rounded-2xl shadow-lg border border-gray-200 dark:border-gray-800 p-4 sm:p-6">
        <div className="text-center">
          <div className="flex justify-center mb-2">
            <div className="relative">
              <div 
                className="absolute inset-0 rounded-full"
                style={{ background: 'linear-gradient(135deg, #f59e0b, #d97706)', filter: 'blur(8px)', opacity: 0.3 }}
              />
              <div className="relative bg-gradient-to-br from-orange-400 to-orange-600 p-2 rounded-full">
                <Shield className="h-10 w-10 text-white" />
              </div>
            </div>
          </div>
          <h2 className="text-xl font-bold text-gray-800">مطلوب تفعيل الحساب</h2>
          <p className="text-gray-700 text-sm mt-1">اختر الباقة المناسبة واضغط زر واتساب للتواصل الفوري.</p>
          
          {/* تم إخفاء زر التحديث اليدوي لأن التحديث أصبح فورياً
          <div className="mt-4 flex justify-center">
             <Button 
               variant="outline" 
               size="sm" 
               onClick={handleRefresh} 
               disabled={isRefreshing}
               className="flex items-center gap-2 text-blue-600 border-blue-200 hover:bg-blue-50"
             >
               <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
               {isRefreshing ? 'جاري التحديث...' : 'تحديث حالة الاشتراك'}
             </Button>
          </div>
          */}
        </div>

        <div className="pt-4">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2 items-stretch">
            {PLANS.map((p) => (
              <div key={p.title} className={`h-full rounded-lg p-2 border shadow-sm bg-gradient-to-br ${p.bg} dark:from-gray-800 dark:to-gray-700 dark:border-gray-700`}>
                <div className="font-bold text-sm text-gray-800 dark:text-gray-100 mb-1">{p.title}</div>
                <div className="text-lg font-extrabold text-gray-900 dark:text-gray-100 mb-2">{p.price} ج</div>
                <ul className="text-[10px] text-gray-700 dark:text-gray-200 text-right space-y-1 mb-2">
                  {p.features.map((f) => (
                    <li key={f}>• {f}</li>
                  ))}
                </ul>
                <Button size="sm" className="w-full bg-green-600 hover:bg-green-700 text-xs py-1 h-8" onClick={() => openWhatsApp(p.title, p.price, p.features)}>
                  تواصل عبر واتساب
                </Button>
              </div>
            ))}
          </div>
        </div>

        <div className="pt-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 mb-2">
              {/* تم إخفاء زر باقة الزيرو بناءً على طلب المستخدم */}
              {/*
            <Button size="sm" className="w-full bg-emerald-600 hover:bg-emerald-700" onClick={handleActivateZeroPlan} disabled={isActivatingTrial}>
              جرب باقة الزيرو
            </Button>
            */}
              {!hasUsedTrial && !isOnFreeTrial && (
                <Button size="sm" className="w-full bg-blue-600 hover:bg-blue-700" onClick={handleActivateTrial} disabled={isActivatingTrial}>
                  {`جرب البرنامج 24 ساعة`}
                </Button>
              )}
              <Button 
                size="sm" 
                className="w-full bg-red-600 hover:bg-red-700" 
                onClick={() => window.open('https://www.youtube.com/@cashylink', '_blank')}
              >
                شرح البرنامج
              </Button>
             </div>
          <Button variant="outline" className="border-2 border-gray-300 hover:border-gray-400 text-gray-700 hover:text-gray-800 px-5 py-2 rounded-lg font-semibold text-xs transition-all duration-300" onClick={signOut}>
            تسجيل الخروج
          </Button>
        </div>
      </div>
    </div>
  );
}
